def can_lexicographically_order(s, t):
    s = sorted(s)
    t = sorted(t)

    if len(s) > len(t):
        return False

    if s == t:
        return False

    for i in range(len(s)):
        if s[i] != t[i]:
            return s[i] < t[i]

    return True

